    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_4,'speak',17,NULL,NULL,'در نخستین تماس با مدیر ساختمان، نام، کشور و شهر محل زندگیت را معرفی کن.','در این موقعیت، پاسخ مناسب را با صدا بگو.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"در نخستین تماس با مدیر ساختمان، نام، کشور و شهر محل زندگیت را معرفی کن.","accepted_intents":["My name is Arman. I am from Iran and I live in London.","I am Arman, from Iran, and I live in London."],"evaluation":"stt","input":"speech","scored":true,"independent":true}' AS JSON),JSON_OBJECT('phase','transfer','typing',FALSE,'novelScenario',TRUE,'masteryCheck',TRUE));
    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_4,'speak',18,NULL,NULL,'در میز خوشامدگویی، نام دوستت و زمان جلسه را با هم بگو.','در این موقعیت، پاسخ مناسب را با صدا بگو.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"در میز خوشامدگویی، نام دوستت و زمان جلسه را با هم بگو.","accepted_intents":["Maya is my friend and the meeting is at eight.","My friend is Maya. The meeting is at eight."],"evaluation":"stt","input":"speech","scored":true,"independent":true}' AS JSON),JSON_OBJECT('phase','transfer','typing',FALSE,'novelScenario',TRUE,'masteryCheck',TRUE));
